# The tunnel's mouth ring: the user's red glass ring (tools/tunnel_ring.png, a transparent hole in a sphere seen from inside) cut round (the square's corners go) and saved as a 512 px WebP
# in src3d/tunnel_ring_assets.js. `hole` = the hole's radius over the picture's half size, `cy` = how far above the picture's centre the hole's centre is (share of the half size).
import base64, io, json, numpy as np
from PIL import Image
im = Image.open('tools/tunnel_ring.png').convert('RGBA'); a = np.array(im); al = a[..., 3]
ys, xs = np.nonzero(al < 10); cx, cy = (xs.min() + xs.max()) / 2, (ys.min() + ys.max()) / 2; hr = ((xs.max() - xs.min()) + (ys.max() - ys.min())) / 4
H = im.size[0] / 2; yy, xx = np.mgrid[0:im.size[1], 0:im.size[0]]; d = np.hypot(xx - H, yy - H)
a[..., 3] = np.where(d > H * 0.985, 0, np.minimum(al, np.clip((H * 0.985 - d) * 0.5 * 255 / 4, 0, 255)).astype(np.uint8))
out = Image.fromarray(a).resize((512, 512), Image.LANCZOS); buf = io.BytesIO(); out.save(buf, 'WEBP', quality=88, method=6)
js = {'src': 'data:image/webp;base64,' + base64.b64encode(buf.getvalue()).decode(), 'hole': round(hr / H, 4), 'cy': round((H - cy) / H, 4)}
open('src3d/tunnel_ring_assets.js', 'w').write('// generated by tools/make_tunnel_ring_assets.py (the user\'s red ring)\nconst TUNNEL_RING = ' + json.dumps(js) + ';\n')
print(js['hole'], js['cy'], len(buf.getvalue()) // 1024, 'KB')
